// The descriptor LVGL draws from. Filled in when first asked for, so the order of the fields does not matter.
inline const lv_image_dsc_t *logo_image() {
  static lv_image_dsc_t dsc;
  static bool ready = false;
  if (!ready) {
    dsc.header.magic = LV_IMAGE_HEADER_MAGIC;
    dsc.header.cf = LV_COLOR_FORMAT_RGB565A8;
    dsc.header.flags = 0;
    dsc.header.w = LOGO_SIZE;
    dsc.header.h = LOGO_SIZE;
    dsc.header.stride = LOGO_SIZE * 2;
    dsc.header.reserved_2 = 0;
    dsc.data_size = sizeof(LOGO_DATA);
    dsc.data = LOGO_DATA;
    dsc.reserved = nullptr;
    dsc.reserved_2 = nullptr;
    ready = true;
  }
  return &dsc;
}

